create table wide (id int, grp int, body text);
select count(*) from wide;
select grp, count(*) from wide group by grp order by grp;
select id from wide where id = 0;
select id from wide where id = 299;
select id from wide where id > 296 order by id;
create index wide_id on wide (id);
select id from wide where id = 150;
select count(*) from wide where id >= 100 and id < 110;
select count(*) from wide where body like 'xxxxxxxxxxxxxxxxxxxx%';
delete from wide where grp = 2;
select count(*) from wide;
select id from wide where id = 150;
select count(*) from wide where id >= 100 and id < 110;
vacuum wide;
select count(*) from wide;
select id from wide where id = 151;
select grp, count(*) from wide group by grp order by grp;
update wide set grp = 9 where id = 1;
select grp, count(*) from wide group by grp order by grp;
